CY.i18n.register("de", {"corner.day": "Tag {n}", "share.note": "Ein Bild, das nur auf deinem Gerät entsteht. Du wählst, was darauf kommt, auch die Namen. Nichts wird hochgeladen, und das Spiel drängt dich nie zum Teilen.", "brand.name": "Care for You", "wd.0": "So", "wd.1": "Mo", "wd.2": "Di", "wd.3": "Mi", "wd.4": "Do", "wd.5": "Fr", "wd.6": "Sa", "tag.1": "Halt kurz inne und kümmere dich um die Menschen zu Hause.", "tag.2": "Nichts ist dringend. Jemand möchte nur, dass du aufschaust.", "tag.3": "Eine kleine Ausrede, fünf Minuten von der Arbeit wegzukommen.", "tag.4": "Keine Punkte. Niemand zählt mit, wie du es machst.", "tag.5": "Du sorgst für sie, und sie sorgen leise für dich.", "tag.6": "Langsam. Sie warten auf dich."});
